const RECENT_KEY = "ninja-era-recent-emojis";
const FREQ_KEY = "ninja-era-emoji-freq";
const MAX_RECENT = 32;

export function loadRecentEmojis(): string[] {
  try {
    const raw = localStorage.getItem(RECENT_KEY);
    if (!raw) return [];
    const arr = JSON.parse(raw);
    return Array.isArray(arr)
      ? filterPickerEmojis(arr.filter((x) => typeof x === "string")).slice(0, MAX_RECENT)
      : [];
  } catch {
    return [];
  }
}

export function pushRecentEmoji(emoji: string) {
  if (!isPickerEmojiAllowed(emoji)) return loadRecentEmojis();
  const next = [emoji, ...loadRecentEmojis().filter((x) => x !== emoji)].slice(0, MAX_RECENT);
  try {
    localStorage.setItem(RECENT_KEY, JSON.stringify(next));
  } catch {
    /* ignore quota */
  }
  bumpEmojiFrequency(emoji);
  return next;
}

type FreqMap = Record<string, number>;

function loadFreqMap(): FreqMap {
  try {
    const raw = localStorage.getItem(FREQ_KEY);
    if (!raw) return {};
    const obj = JSON.parse(raw);
    return obj && typeof obj === "object" ? obj as FreqMap : {};
  } catch {
    return {};
  }
}

export function bumpEmojiFrequency(emoji: string) {
  if (!isPickerEmojiAllowed(emoji)) return;
  const map = loadFreqMap();
  map[emoji] = (map[emoji] || 0) + 1;
  try {
    localStorage.setItem(FREQ_KEY, JSON.stringify(map));
  } catch {
    /* ignore */
  }
}

/** Most-used emojis for this browser profile. */
export function loadFrequentEmojis(limit = 32): string[] {
  const map = loadFreqMap();
  return filterPickerEmojis(
    Object.entries(map)
      .sort((a, b) => b[1] - a[1])
      .map(([e]) => e),
  ).slice(0, limit);
}
